REPLACE INTO `form_manager` (`id`, `slug`, `table_name`, `title`, `description`, `roles`, `react_route`, `submit_endpoint`, `http_method`, `status`, `version`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 'form-constructor', NULL, 'Construtor de Formularios', 'Meta-formulario: cada grupo abaixo define os campos de uma das quatro tabelas do modulo Form. Preencha de cima para baixo — o formulario alimenta o grupo, o grupo alimenta a linha, a linha alimenta o campo.', 'admin', '/v1/form-constructor', '/api/v1/form-manager/create', 'POST', 'active', 1, '2026-09-10 13:30:04', '2026-09-10 13:30:04', NULL),
	(2, 'calendario', NULL, 'Calendário', 'Cadastro de Calendário', '["guest","user","admin"]', '/v1/calendar-manager/create', '/api/v1/calendar-manager/create', 'POST', 'active', 1, '2026-09-10 16:37:56', '2026-09-10 19:43:08', NULL),
	(3, 'cadastro-usuario', 'user_manager', 'Usuário (Segurança)', 'Primeira etapa de cadastro de usuários.', '["guest","user","admin"]', '/v1/user-manager/create', '/api/v1/user-manager/create', 'POST', 'active', 1, '2026-09-14 15:52:09', '2026-09-14 17:11:49', NULL),
	(4, 'dados-do-usuario', 'user_profiles', 'Usuário (Dados)', 'Cadastro da segunda etapa do Fomulário', '["guest","user","admin"]', '/v1/user-manager/create', '/api/v1/user-profiles/create', 'POST', 'active', 1, '2026-09-14 15:56:49', '2026-09-14 17:12:09', NULL),
	(5, 'usuario-autenticacao', 'user_manager', 'Usuário (Autenticação)', 'Tela de Login do Usuário', NULL, '/v1/user-auth', '/api/v1/auth', 'POST', 'draft', 1, '2026-09-14 20:17:30', '2026-09-14 20:17:30', NULL),
	(6, 'atualizar-usuario', NULL, 'Usuário (Segurança)', 'Atualização de credenciais/acesso: usuário, status, papel e (opcional) troca de senha. Edita apenas user_manager — dados de perfil (nome, e-mail, telefone) ficam no formulário de Dados (user_profiles).', '["admin"]', '/v1/user-manager/update', '/api/v1/user-manager/update', 'PUT', 'active', 1, '2026-09-15 19:18:22', '2026-09-15 19:29:04', NULL);

